const j = $input.first()?.json ?? {};
const consumer = j.consumer_input;
const routing = j.routing_input;
function fail(code, detail) { throw new Error(code + (detail ? ': ' + detail : '')); }
if (!consumer || typeof consumer !== 'object' || Array.isArray(consumer)) fail('CANONICAL_CONSUMER_INPUT_REQUIRED');
if (!routing || typeof routing !== 'object' || Array.isArray(routing)) fail('CANONICAL_ROUTING_INPUT_REQUIRED');
if (routing.schema !== 'planner-routing-input-v1') fail('ROUTING_SCHEMA_INVALID');
if (!consumer.task_id || consumer.task_id !== routing.task_id) fail('TASK_ID_MISMATCH');
if (!['glm','codex'].includes(routing.preferred)) fail('REMOTE_PLANNER_ONLY');
if (consumer.planner_requested !== routing.preferred) fail('PLANNER_REQUEST_MISMATCH');
if (!Array.isArray(routing.fallback) || routing.fallback.length !== 0) fail('PLANNER_FALLBACK_FORBIDDEN');
if (routing.fallback_policy !== 'gate_only') fail('FALLBACK_POLICY_MUST_BE_GATE_ONLY');
if (routing.preferred === 'qwen' || routing.fallback.includes('qwen') || consumer.planner_requested === 'qwen') fail('QWEN_DEFERRED');
return [{json:{
  task_id:consumer.task_id,
  consumer_b64:Buffer.from(JSON.stringify(consumer),'utf8').toString('base64'),
  routing_b64:Buffer.from(JSON.stringify(routing),'utf8').toString('base64')
}}];

const r=$json;
const stdout=String(r.stdout??'').trim();
const exitCode=Number(r.exitCode??r.code??1);
let parsed=null;
try{const lines=stdout.split(/\r?\n/).filter(Boolean);parsed=lines.length?JSON.parse(lines[lines.length-1]):null;}catch{}
const ingress=$('Validate canonical ingress + encode').item.json;
const ready=exitCode===0&&parsed?.ok===true&&parsed?.classification==='PASS'&&parsed?.request_envelope?.body;
const requestBody=ready?parsed.request_envelope.body:null;
return {json:{
 task_id:ingress.task_id,consumer_b64:ingress.consumer_b64,
 prepare_ready:Boolean(ready),prepare_result:parsed,prepare_exit_code:exitCode,
 request_body:requestBody,
 request_body_b64:ready?Buffer.from(JSON.stringify(requestBody),'utf8').toString('base64'):null,
 classification:ready?'PASS':(parsed?.classification||'PREPARE_FAILED')
}};

const r=$json;
const stdout=String(r.stdout??'').trim();
const exitCode=Number(r.exitCode??r.code??1);
let bridge=null;
try{const lines=stdout.split(/\r?\n/).filter(Boolean);bridge=lines.length?JSON.parse(lines[lines.length-1]):null;}catch{}
const prep=$('Parse prepare result fail-closed').item.json;
const transportOk=exitCode===0&&bridge?.schema==='litellm-primary-http-one-shot-v1'&&bridge?.ok===true;
const status=Number(bridge?.statusCode??0);
let raw='';
if(typeof bridge?.body_b64==='string'&&bridge.body_b64.length>0){try{raw=Buffer.from(bridge.body_b64,'base64').toString('utf8');}catch{raw='';}}
function add(set,arr,v,limit){if(typeof v!=='string'||!v||set.has(v)||arr.length>=limit)return;set.add(v);arr.push(v);}
function shape(v){if(Array.isArray(v)){const first=v[0];return first&&typeof first==='object'&&!Array.isArray(first)?'array<object:'+Object.keys(first).sort().slice(0,32).join(',')+'>':'array';}if(v&&typeof v==='object')return 'object:'+Object.keys(v).sort().slice(0,32).join(',');return typeof v;}
function census(text){
 const labels=[],types=[],keySets=[],fieldShapes=[],orderedTypes=[];
 const sl=new Set(),st=new Set(),sk=new Set(),sf=new Set();
 let dataEventCount=0,doneMarkerCount=0,parseErrorCount=0;
 const selected=['response','item','delta','content','output','choices','message'];
 for(const rawLine of String(text??'').split(/\r?\n/)){
  const line=rawLine.trim();if(!line)continue;
  if(line.startsWith('event:')){add(sl,labels,line.slice(6).trim(),32);continue;}
  if(!line.startsWith('data:'))continue;
  dataEventCount+=1;const payload=line.slice(5).trim();
  if(payload==='[DONE]'){doneMarkerCount+=1;continue;}
  let p;try{p=JSON.parse(payload);}catch{parseErrorCount+=1;continue;}
  if(!p||typeof p!=='object'||Array.isArray(p))continue;
  const keys=Object.keys(p).sort();add(sk,keySets,keys.join('|'),32);
  if(typeof p.type==='string'){add(st,types,p.type,64);if(orderedTypes.length<256)orderedTypes.push(p.type);}
  for(const k of selected){if(!(k in p))continue;add(sf,fieldShapes,k+'='+shape(p[k]),64);const v=p[k];if(Array.isArray(v)&&v[0]&&typeof v[0]==='object'&&!Array.isArray(v[0])){for(const nk of ['delta','message','content']){if(nk in v[0])add(sf,fieldShapes,k+'[0].'+nk+'='+shape(v[0][nk]),64);}}}
 }
 return {schema:'sse-structural-census-v1',data_event_count:dataEventCount,done_marker_count:doneMarkerCount,parse_error_count:parseErrorCount,event_labels:labels,event_types:types,first_event_types:orderedTypes.slice(0,8),last_event_types:orderedTypes.slice(-8),top_level_key_sets:keySets,selected_field_shapes:fieldShapes};
}
function bodyShape(text){
 const t=String(text??'').trim();
 const selected=['object','type','status','id','response','output','choices','message','content','delta','usage','error'];
 const out={schema:'http-body-structural-census-v1',framing:'TEXT_OTHER',top_level_keys:[],selected_field_shapes:[],first_array_item_keys:[],nested_key_sets:[]};
 if(!t)return {...out,framing:'EMPTY'};
 let parsed,parsedOk=false;
 try{parsed=JSON.parse(t);parsedOk=true;}catch{}
 if(parsedOk){
  if(Array.isArray(parsed)){
   out.framing='JSON_ARRAY';
   const first=parsed[0];
   if(first&&typeof first==='object'&&!Array.isArray(first)){
    out.first_array_item_keys=Object.keys(first).sort().slice(0,64);
    for(const k of selected){if(k in first)out.selected_field_shapes.push('item0.'+k+'='+shape(first[k]));}
   }
   return out;
  }
  if(parsed&&typeof parsed==='object'){
   out.framing='JSON_OBJECT';
   out.top_level_keys=Object.keys(parsed).sort().slice(0,64);
   for(const k of selected){
    if(!(k in parsed))continue;
    out.selected_field_shapes.push(k+'='+shape(parsed[k]));
    const v=parsed[k];
    if(v&&typeof v==='object'&&!Array.isArray(v))out.nested_key_sets.push(k+'='+Object.keys(v).sort().slice(0,64).join('|'));
    if(Array.isArray(v)&&v[0]&&typeof v[0]==='object'&&!Array.isArray(v[0]))out.nested_key_sets.push(k+'[0]='+Object.keys(v[0]).sort().slice(0,64).join('|'));
   }
   return out;
  }
  return {...out,framing:'JSON_SCALAR'};
 }
 const lines=t.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
 if(lines.some(x=>x.startsWith('data:')||x.startsWith('event:')))return {...out,framing:'SSE_DATA_LINES'};
 if(lines.length>1){let n=0;for(const line of lines){try{const p=JSON.parse(line);if(p&&typeof p==='object')n+=1;}catch{}}if(n===lines.length)return {...out,framing:'NDJSON'};}
 return out;
}
return {json:{
 task_id:prep.task_id,consumer_b64:prep.consumer_b64,
 http_status:Number.isFinite(status)?status:0,
 http_ok:Boolean(transportOk&&status>=200&&status<300),
 response_b64:transportOk&&typeof bridge.body_b64==='string'?bridge.body_b64:null,
 transport_classification:bridge?.classification||'HTTP_BRIDGE_OUTPUT_INVALID',
 transport_elapsed_ms:Number.isFinite(Number(bridge?.elapsed_ms))?Number(bridge.elapsed_ms):null,
 transport_body_bytes:Number.isFinite(Number(bridge?.body_bytes))?Number(bridge.body_bytes):0,
 sse_census:census(raw),body_shape:bodyShape(raw)
}};

const r=$json;
const stdout=String(r.stdout??'').trim();
const exitCode=Number(r.exitCode??r.code??1);
let parsed=null;
try{const lines=stdout.split(/\r?\n/).filter(Boolean);parsed=lines.length?JSON.parse(lines[lines.length-1]):null;}catch{}
const http=$('Capture HTTP body + status').item.json;
const ok=exitCode===0&&parsed?.ok===true&&parsed?.classification==='PASS';
const packetCensus=parsed?.packet_census_before_completion??parsed?.packet_census??null;
const completion=parsed?.deterministic_completion??null;
return {json:ok?{
 schema:'n8n-litellm-primary-cycle-result-v1',ok:true,classification:'PASS',task_id:http.task_id,http_status:http.http_status,
 response_source_format:parsed.response_source_format,response_gate:parsed.response_gate,packet:parsed.packet,policy:parsed.policy,
